function loadFromHtml(html, baseUrl) {
  try {
    var doc = new DOMParser().parseFromString(html, "text/html");
    var base = doc.createElement("base");
    base.href = baseUrl || new URL("./", new URL(URL_, document.baseURI)).href;

    if (doc.head) {
      doc.head.insertBefore(base, doc.head.firstChild);
    } else {
      var head = doc.createElement("head");
      head.appendChild(base);
      doc.documentElement.insertBefore(head, doc.body || null);
    }

    var fullHtml = "<!doctype html>\n" + doc.documentElement.outerHTML;
    var blob = new Blob([fullHtml], { type: "text/html" });
    var blobUrl = URL.createObjectURL(blob);
    frame.src = blobUrl;
  } catch (e) {
    showError(e);
  }
}

function showError(message) {
  if (EMBEDDED_HTML) {
    loadFromHtml(decodeURIComponent(EMBEDDED_HTML), document.baseURI);
    return;
  }
  frame.srcdoc =
    "<!doctype html><html><body style='margin:0;padding:24px;" +
    "font:14px system-ui;color:#b00;background:#090b10'>" +
    "<pre style='white-space:pre-wrap'>" +
    String(message).replace(/&/g,"&amp;").replace(/</g,"&lt;") +
    "</pre></body></html>";
}

var loaded = false;
var fallbackTimer = setTimeout(function() {
  if (!loaded) {
    loaded = true;
    if (EMBEDDED_HTML) {
      loadFromHtml(decodeURIComponent(EMBEDDED_HTML), document.baseURI);
    }
  }
}, 1200);

try {
  var targetUrl = new URL(URL_, document.baseURI).href;
  fetch(targetUrl, { credentials: "same-origin" })
    .then(function (response) {
      if (!response.ok) {
        throw new Error("HTTP " + response.status + " while loading " + URL_);
      }
      return response.text();
    })
    .then(function (html) {
      if (!loaded) {
        loaded = true;
        clearTimeout(fallbackTimer);
        loadFromHtml(html, new URL("./", targetUrl).href);
      }
    })
    .catch(function (err) {
      if (!loaded) {
        loaded = true;
        clearTimeout(fallbackTimer);
        showError(err);
      }
    });
} catch (err) {
  if (!loaded) {
    loaded = true;
    clearTimeout(fallbackTimer);
    showError(err);
  }
}
